python3 -c "
def weight(n):
    return bin(n).count('1')

for n in range(1, 8):
    even = sum(1 for i in range(1, 2**n + 1) if weight(i) % 2 == 0)
    odd  = sum(1 for i in range(1, 2**n + 1) if weight(i) % 2 == 1)
    print(f'n={n}: 2^n={2**n}, even={even}, odd={odd}, diff(even-odd)={even-odd}')
"

